BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-19806'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='3A0407' OR source_url ~ '[?&]id=19806(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='c5400407-69dd-45a6-977c-618665519806' OR slug='sam-na-san-phra-phrom-land-59-rai-3a0407' OR (abs(latitude-8.376831)<0.0001 AND abs(longitude-99.92149)<0.0001 AND abs(land_area_sqm-95820)<1)) THEN RAISE NOTICE 'SAM 3A0407 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('c5400407-69dd-45a6-977c-618665519806', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'land', 'business', 'sale', 'whole_property', 'ที่ดิน 59 ไร่ 3 งาน 55 ตร.ว. ติด ทล.4103 นาสาร พระพรหม', 'รายละเอียดทรัพย์

ที่ดินเปล่า 11 แปลงติดต่อกัน ถนนสายนาพรุ–ปากพูน (ทล.4103) ตำบลนาสาร อำเภอพระพรหม จังหวัดนครศรีธรรมราช เนื้อที่รวม 59 ไร่ 3 งาน 55 ตร.ว. หรือ 23,955 ตร.ว. (95,820 ตร.ม.) ราคาประกาศขายทั้งทรัพย์ 123,129,000 บาท รหัส SAM 3A0407 เอกสารสิทธิ์โฉนดเลขที่ 23020, 23021, 23022, 23026, 23028, 23029, 23030, 23328, 25580, 26146 และ 28889 รวม 11 ฉบับ

ลักษณะที่ดินและการเข้าถึง

แปลงรวมรูปหลายเหลี่ยม ด้านตะวันออกติดถนนกว้างประมาณ 190 เมตร ลึกสุดประมาณ 557 เมตร ระดับที่ดินต่ำกว่าถนนประมาณ 1 เมตร ภายในมีบ่อน้ำขนาดประมาณ 18 × 60 เมตร ลึกประมาณ 1.5–2 เมตร SAM ระบุพื้นที่บ่อประมาณ 2 งาน 71 ตร.ว. ตัวเลขขนาดและพื้นที่เป็นค่าประมาณจากต้นทาง ควรตรวจสภาพ ระดับดิน การระบายน้ำและเนื้อที่ใช้งานจริง

ถนนหน้าทรัพย์เป็นทางสาธารณประโยชน์ ผิวลาดยางกว้างประมาณ 18 เมตร เขตทางประมาณ 100 เมตร ตาม SAM ตั้งอยู่ในย่านที่อยู่อาศัยและอุตสาหกรรม จากอำเภอหัวไทรมุ่งหน้าท่าศาลาทาง ทล.4103 ขึ้นสะพานข้ามแยกนาพรุ ตรงไปประมาณ 3.4 กม. ถึงบริเวณ กม.21 ทรัพย์อยู่ซ้ายมือ

ข้อควรทราบก่อนเสนอซื้อ

ที่ตั้งในส่วนสรุปประกาศ SAM ระบุอำเภอพระพรหม แต่หน้าโฉนดระบุอำเภอเมืองนครศรีธรรมราช ตำบลนาสาร จังหวัดนครศรีธรรมราช ควรตรวจความสอดคล้องของเอกสารกับเขตปกครองและแนวเขตปัจจุบัน

SAM ระบุสีผังเมืองเป็นสีขาวมีกรอบและเส้นทแยงสีเขียว และระบุข้อบังคับควบคุมอาคารเรื่องระยะร่นจากเขตทางหลวงไม่น้อยกว่า 6 เมตร รวมถึงเทศบัญญัติเทศบาลตำบลนาสาร ข้อมูลนี้เป็นข้อระบุของต้นทาง ไม่ใช่การยืนยันสิทธิพัฒนาหรืออนุญาตก่อสร้าง ผู้สนใจควรตรวจผังเมือง ระยะร่นและข้อกำหนดที่ใช้บังคับปัจจุบันกับหน่วยงานที่เกี่ยวข้องตามโครงการที่ต้องการทำ

ภาพและการติดต่อ

ภาพจริงและผังจาก SAM คัดไม่ซ้ำ 10 ภาพ มีภาพลงวันที่ 24 มกราคม 2564 และ 24 มกราคม 2565 แสดงหน้าที่ดิน สภาพภายใน บ่อน้ำ ผังแปลงและแผนที่ ควรนัดดูสภาพปัจจุบัน ต้นทางไม่ยืนยันผู้ใช้ประโยชน์ ภาระผูกพันปัจจุบันหรือระบบสาธารณูปโภคภายในครบถ้วน

พิกัด 8.376831, 99.921490 ดึงจากลิงก์นำทาง SAM และตรงกับลิงก์แผนที่ เป็นจุดอ้างอิง ไม่ใช่แนวเขตรังวัด ตรวจราคาและสถานะซื้อตรงวันที่ 15 กันยายน 2569 ติดต่อ SAM โทร.02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 3A0407 เพื่อยืนยันราคา เอกสาร เนื้อที่และเงื่อนไขล่าสุด', 123129000, false, 95820, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'ถนนสายนาพรุ–ปากพูน ทล.4103 กม.21', 'ที่ดิน 11 แปลงติดต่อกัน', 'ถนนสายนาพรุ–ปากพูน (ทล.4103)', 8.376831, 99.92149, 'นครศรีธรรมราช', 'พระพรหม', 'นาสาร', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-na-san-phra-phrom-land-59-rai-3a0407') RETURNING id INTO property_listing_id;
