INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', '59 Rai Land on Highway 4103, Na San, Phra Phrom', 'Eleven adjoining vacant land plots on Na Phru–Pak Phun Road (Highway 4103), Na San, Phra Phrom, Nakhon Si Thammarat. Total 59 rai 3 ngan 55 sq.wah, or 23,955 sq.wah (95,820 sq.m.). SAM whole-property asking price THB 123,129,000, reference 3A0407. Eleven Chanote titles: 23020, 23021, 23022, 23026, 23028, 23029, 23030, 23328, 25580, 26146 and 28889.

Irregular combined plot with approximately 190 m eastern road frontage and maximum depth 557 m. Land is approximately 1 m below road level. Pond approximately 18 by 60 m, 1.5–2 m deep; SAM states approximately 271 sq.wah. Measurements are approximate; inspect actual usable area, ground levels and drainage. SAM describes a public paved road, approximately 18 m carriageway and 100 m right of way, in residential/industrial surroundings. From Hua Sai toward Tha Sala on Highway 4103, cross Na Phru junction flyover and continue approximately 3.4 km to km 21; property on left.

Source summary uses Phra Phrom district, whereas the title address states Mueang Nakhon Si Thammarat district, Na San. Verify documents against current administrative boundaries. SAM lists white zoning with green border and diagonal lines, a minimum 6 m building setback from the highway boundary and Na San municipal ordinances. These are source-attributed statements, not confirmation of development permission. Check current planning, setbacks and project-specific requirements with authorities.

Ten unique authentic source photos/plans include photos dated 24 January 2021 and 24 January 2022. Current occupancy, encumbrances and full on-site utilities are unconfirmed. Navigation and map agree at 8.376831, 99.921490, a reference point rather than surveyed boundaries. Direct-sale price/status checked 15 September 2026. Contact SAM at 02-686-1888, sales@sam.or.th or LINE @samline quoting 3A0407.', 'Na Phru–Pak Phun Highway 4103, km21', 'Eleven adjoining land plots', 'Na Phru–Pak Phun Highway 4103', 'Na San', 'Phra Phrom', 'Nakhon Si Thammarat', '59 Rai Land on Highway 4103, Na San, Phra Phrom', 'Eleven adjoining plots,95820sqm,THB123129000; pond, ground levels, title address difference and source setback disclosed.', 'published', 'ai_assisted', now(), '59 rai land on highway 4103, na san, phra phrom eleven adjoining vacant land plots on na phru–pak phun road (highway 4103), na san, phra phrom, nakhon si thammarat. total 59 rai 3 ngan 55 sq.wah, or 23,955 sq.wah (95,820 sq.m.). sam whole-property asking price thb 123,129,000, reference 3a0407. eleven chanote titles: 23020, 23021, 23022, 23026, 23028, 23029, 23030, 23328, 25580, 26146 and 28889.

